// Adapted from w22 src/services/refundService.ts @ a0d6e0d (createRefundForPayment, lines 18-101: the transaction body is VERBATIM),
// src/lib/domain/paymentStateMachine.ts:52-63 (assertRefundAllowed, verbatim minus type annotations) and src/lib/errors.ts (RouteError).
// Prisma and the repositories become an in-memory store with the same call shapes (refundRepository.ts,
// paymentRepository.ts, paymentEventRepository.ts); the store is passed in as `prisma` instead of imported.
// The repo's "SENIOR NOTE" review annotations are left out of both copied bodies.
export class RouteError extends Error {
  constructor(status, code, message, details) {
    super(message);
    this.status = status;
    this.code = code;
    this.details = details;
  }
}

const RefundStatus = { PENDING: "PENDING", SUCCEEDED: "SUCCEEDED", FAILED: "FAILED" };

export function assertRefundAllowed(
  currentStatus,
  refundAmountMinor,
  capturedAmountMinor,
) {
  if (currentStatus !== "SUCCEEDED") {
    throw new RouteError(409, "PAYMENT_NOT_REFUNDABLE", "Only succeeded payments can be refunded.");
  }

  if (refundAmountMinor > capturedAmountMinor) {
    throw new RouteError(409, "REFUND_AMOUNT_EXCEEDS_CAPTURE", "Refund amount exceeds the captured payment amount.");
  }
}

/** In-memory stand-in for the Prisma client: $transaction hands the callback this same store as `tx`. */
export function createStore({ payments = [], refunds = [] } = {}) {
  return {
    payments,
    refunds,
    events: [],
    async $transaction(fn) {
      return fn(this);
    },
  };
}

// repository stand-ins (same arguments as the real repositories, client last)
async function findPaymentById(id, db) {
  // like prisma.payment.findUnique: a fresh object, not a live reference to the stored row
  const payment = db.payments.find((candidate) => candidate.id === id);
  return payment ? { ...payment } : null;
}
async function sumSuccessfulRefundsForPayment(paymentId, db) {
  return db.refunds.filter((r) => r.paymentId === paymentId && r.status === RefundStatus.SUCCEEDED).reduce((sum, r) => sum + r.amountMinor, 0);
}
async function createRefund(input, db) {
  const refund = { id: `refund-${db.refunds.length + 1}`, ...input, status: RefundStatus.PENDING };
  db.refunds.push(refund);
  return refund;
}
async function transitionRefundStatus(refundId, status, providerRefundId, db) {
  const refund = db.refunds.find((r) => r.id === refundId);
  Object.assign(refund, { status, providerRefundId });
  return refund;
}
async function transitionPaymentStatus(input, db) {
  const payment = db.payments.find((p) => p.id === input.paymentId);
  Object.assign(payment, { status: input.nextStatus, lastKnownProvider: input.providerStatus });
  return payment;
}
async function createPaymentEvent(input, db) {
  db.events.push(input);
  return input;
}

export async function createRefundForPayment(input, prisma) {
  return prisma.$transaction(async (tx) => {
    // Read the payment and successful refund total on the same transaction
    // client as the write. This keeps the allowance check with the mutation.
    const payment = await findPaymentById(input.paymentId, tx);
    if (!payment) {
      throw new RouteError(404, "PAYMENT_NOT_FOUND", "Payment not found.");
    }
    const refundedAmount = await sumSuccessfulRefundsForPayment(payment.id, tx);
    const remainingRefundableAmount = payment.amountMinor - refundedAmount;
    assertRefundAllowed(payment.status, input.amountMinor, remainingRefundableAmount);

    const refund = await createRefund(
      {
        paymentId: payment.id,
        amountMinor: input.amountMinor,
        reason: input.reason,
        createdByUserId: input.session.userId,
      },
      tx,
    );

    await createPaymentEvent(
      {
        paymentId: payment.id,
        actorUserId: input.session.userId,
        actorLabel: input.session.email,
        type: "REFUND_REQUESTED",
        payload: {
          refundId: refund.id,
          amountMinor: refund.amountMinor,
          reason: refund.reason,
        },
      },
      tx,
    );

    const providerRefundId = `prov_ref_${crypto.randomUUID()}`;
    await transitionRefundStatus(refund.id, RefundStatus.SUCCEEDED, providerRefundId, tx);

    const fullyRefunded = refundedAmount + refund.amountMinor === payment.amountMinor;

    if (fullyRefunded) {
      await transitionPaymentStatus(
        {
          paymentId: payment.id,
          nextStatus: "REFUNDED",
          providerStatus: "REFUNDED",
        },
        tx,
      );
    }

    await createPaymentEvent(
      {
        paymentId: payment.id,
        actorUserId: input.session.userId,
        actorLabel: input.session.email,
        type: "REFUND_SUCCEEDED",
        payload: {
          refundId: refund.id,
          providerRefundId,
          fullyRefunded,
        },
      },
      tx,
    );

    return {
      refundId: refund.id,
      paymentId: payment.id,
      refundStatus: "SUCCEEDED",
      paymentStatus: fullyRefunded ? "REFUNDED" : payment.status,
      providerRefundId,
    };
  });
}

